  W.def('ABrazilGev', int(brGev)); W.def('ABrazilGevNeg', int(brGevNeg));
  W.def('ACorner', int(corner)); W.def('ACornerGev', int(cornerGev)); W.def('ACornerPos', int(cornerPos)); W.def('ACornerLowest', int(cornerLowest)); W.def('ACornerSevenRefused', int(cornerSevenR));
  const cnt = (o, k) => int(o[k] || 0);
