  W.rows('ANaiveRows', SIX.map((f) => [FAMT[f]].concat(BLK.map((b) => cnt(naive[b], f)))).concat([['refused'].concat(BLK.map((b) => cnt(naive[b], 'R')))]));
  W.rows('ASevenRows', SIX.concat(['gev']).map((f) => [FAMT[f]].concat(BLK.map((b) => cnt(seven[b], f)))).concat([['refused'].concat(BLK.map((b) => cnt(seven[b], 'R')))]));
  for (const b of BLK) { W.def('ADecided' + b[0].toUpperCase() + b.slice(1), int(t.blocks / 3 - (by[b].R || 0))); W.def('ARefusedChoice' + b[0].toUpperCase() + b.slice(1), int(by[b].R || 0)); W.def('ANaiveDiff' + b[0].toUpperCase() + b.slice(1), int(diffBy[b])); W.def('AWeibull' + b[0].toUpperCase() + b.slice(1), int(by[b].weibull || 0)); W.def('AEw' + b[0].toUpperCase() + b.slice(1), int(by[b].expweibull || 0)); }
  const diff = diffBy.daily + diffBy.weekly + diffBy.monthly;
  W.def('ANaiveDiff', int(diff)); W.def('ANaiveDiffPct', pct(100 * diff / t.blocks, 1));
  W.def('ARefusedChoices', int(BLK.reduce((s, b) => s + (by[b].R || 0), 0)));
  W.def('ABelow', int(below)); W.def('ALeveled', int(leveled)); W.def('ABelowPct', pct(100 * below / leveled, 0));
  const med = (a) => { const s = a.slice().sort((x, y) => x - y); return s[Math.floor(s.length / 2)]; };
  W.def('AUncDaily', pct(100 * med(unc.daily), 0)); W.def('AUncWeekly', pct(100 * med(unc.weekly), 0)); W.def('AUncMonthly', pct(100 * med(unc.monthly), 0));
  const eiS = ei.map((q) => q.v).sort((x, y) => x - y);
  W.def('AEiLo', dec(eiS[0], 2)); W.def('AEiHi', dec(eiS[eiS.length - 1], 2)); W.def('AEiMedian', dec(med(eiS), 2)); W.def('AEiCells', int(eiS.length));
  const rs = ratios.slice().sort((x, y) => x - y);
  W.def('ARatioMedian', dec(med(rs), 2)); W.def('ARatioNinety', dec(rs[Math.floor(0.9 * rs.length)], 2)); W.def('ARatioAboveTwo', int(rs.filter((r) => r > 2).length)); W.def('ARatioAboveFive', int(rs.filter((r) => r > 5).length));
  need(worst && worst.c.lat === 15 && worst.c.lon === 62, 'the worst ratio is no longer the Arabian Sea cell');
  W.def('AWorstRatio', dec(worst.r, 1)); W.def('AWorstLevel', dec(worst.v, 1)); W.def('AWorstMax', dec(worst.max, 2)); W.def('AWorstBlock', worst.bn); W.def('AWorstFamily', FAMT[worst.f]); W.def('AWorstLat', String(worst.c.lat)); W.def('AWorstLon', String(worst.c.lon));
  const ar = sea.find((c) => c.id === '15_62');
