    if (cs[0].by) return cs.map((c) => Object.entries(c.by).sort((a, b) => b[1] - a[1]).map(([f, n]) => FAMT[f] + ' ' + n).join(', ') + ' of ' + c.n + ' (refused ' + c.refused + ')').join('; ');
