  const ew = L.scipy.buoys.A.native.expweibull;
  need(ew.floc0.verdict === 'AGREES' && ew.default.verdict === 'BELOW_A_MEMBER', 'the buoy-A exponentiated-Weibull pair changed');
  W.def('SEwFixed', dec(ew.floc0.level100, 2)); W.def('SEwFree', dec(ew.default.level100, 2)); W.def('SEwDeficit', int(ew.default.deficit)); W.def('SEwFreeLoc', dec(ew.default.loc, 4)); W.def('SEwFreeParams', ew.default.params.map((x) => Number(x).toPrecision(4)).join(', ')); W.def('SEwFixedParams', ew.floc0.params.map((x) => Number(x).toPrecision(4)).join(', '));
  W.def('SShiftLo', dec(shift[0], 2)); W.def('SShiftHi', sgn(shift[1], 2));
  const scRows = [];
