  W.rows('SRows', scRows);
  /* ---- a published design table ---- */
  const lev = T.summary.levels;
  need(T.summary.decided === 20 && lev.length === 20, 'the design table no longer has 20 decided rows');
  W.def('TRows', String(T.summary.decided)); W.def('TOff', String(T.summary.verdicts['OFF THE MAXIMUM'] || 0)); W.def('TOutsideSupport', String(T.summary.verdicts['OUTSIDE ITS SUPPORT'] || 0));
  W.def('TOutsideNinetyFive', String(lev.filter((x) => x.outside).length)); W.def('TDMin', sgn(Math.min(...lev.map((x) => x.d)), 2)); W.def('TDMax', sgn(Math.max(...lev.map((x) => x.d)), 2));
