  W.rows('TAreaRows', T.rows.map((q) => [tex(q.name), dec(q.lat, 2), dec(q.lon, 2), q.cells[0].id.replace('_', ', '), String(q.cells[0].km), dec(q.cells[0].max, 2), dec(q.cells[0].gumbel.l100[1], 2), dec(q.cells[0].gev.l100[1], 2)]));
  const acu = T.rows.find((q) => /A[cç]u/.test(q.name));
  if (acu) { W.def('TAcuNear', dec(acu.cells[0].gumbel.l100[1], 2)); W.def('TAcuNext', dec(acu.cells[1].gumbel.l100[1], 2)); W.def('TAcuKm', String(acu.cells[0].km)); W.def('TAcuKmNext', String(acu.cells[1].km)); }
  W.def('TBlock', tex(T.conventions.block));
  /* ---- the benchmark's printed marginals ---- */
  const P = L.printed, prow = (id, b) => P.rows.find((q) => q.id === id && q.buoy === b);
  const pA = ['c12', 'c3', 'c4', 'c8', 'c9'].map((id) => prow(id, 'A'));
  W.def('BRows', String(P.rows.length)); W.def('BSpreadLo', dec(Math.min(...pA.map((q) => Number(q.rl100.lo))), 2)); W.def('BSpreadHi', dec(Math.max(...pA.map((q) => Number(q.rl100.hi))), 2));
