  const CONTRIB = { c12: '1 \\& 2', c3: '3', c4: '4', c8: '8', c9: '9' };
  const verdictOf = (q) => { if (q.id === 'c8' && q.reproducesTz) return 'the certified Weibull MLE of the zero-up-crossing period, not of $H_s$'; if (q.reproduces && q.id === 'c3') return 'a certified local maximum of an unbounded likelihood'; if (q.reproduces) return 'the rounding of the certified MLE'; if (q.belowLocation[0] > 0) return int(q.belowLocation[0]) + ' hours below the printed location'; if (q.belowLocation[1] > 0) return 'location at the smallest hour to the digits; undecided'; if (q.deficit && Number(q.deficit.lo) > 0) return 'below the certified maximum by ' + int(Number(q.deficit.lo)) + ' or more (least squares by design)'; return 'not maximum likelihood (weighted least squares)'; };
  W.rows('BPrintedRows', ['c12', 'c3', 'c4', 'c8', 'c9'].flatMap((id) => BUOYS.map((b) => { const q = prow(id, b); return [CONTRIB[id], b, FAMT[q.family], q.printed.join(', '), verdictOf(q), dec(q.rl100.lo, 2) + '--' + dec(q.rl100.hi, 2)]; })));
